mod tests {
    use super::*;
    use crate::changelog::ChangelogEntry;
    use callisto_model::{PackageId, Severity, Version, VersionGrammar};

    fn make_input(summary: &str) -> ChangelogInput {
        ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
            entries: vec![ChangelogEntry {
                severity: Severity::Patch,
                source: ChangeSource::Changeset {
                    filename: "fix.md".to_string(),
                    summary: summary.to_string(),
                },
            }],
        }
    }

    #[test]
    fn renders_basic_changelog_section() {
        let input = ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
            entries: vec![ChangelogEntry {
                severity: Severity::Minor,
                source: ChangeSource::Changeset {
                    filename: "cool-dragons.md".to_string(),
                    summary: "Add dragon feature".to_string(),
                },
            }],
        };

        let rendered = render_section(&input).unwrap();
        assert!(rendered.contains("## 1.1.0"));
        assert!(!rendered.contains("### Minor Changes"));
        assert!(!rendered.contains("### Patch Changes"));
        assert!(rendered.contains("- Add dragon feature"));
    }

    #[test]
    fn render_section_flattens_mixed_severities_into_one_list() {
        // A package released alongside a fixed group can carry entries of
        // different originally-authored severities (e.g. a patch-level fix
        // plus a group-driven minor bump). The rendered changelog must not
        // re-surface that per-entry severity distinction -- the version
        // heading already communicates the one, real applied bump.
        let input = ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
            entries: vec![
                ChangelogEntry {
                    severity: Severity::Minor,
                    source: ChangeSource::GroupUnion {
    changelog_path: &Path,
    display_name: &str,
    rendered: &str,
    permit: &ApplyPermit,
) -> Result<(), ChangelogError> {
    let full_path = root.join(changelog_path);
    if let Some(parent) = full_path.parent() {
        fs::create_dir_all(parent).map_err(|e| ChangelogError::WriteFailed {
            path: changelog_path.to_path_buf(),
            message: e.to_string(),
        })?;
    }

    let existing = callisto_model::strict_fs::read_optional(&full_path)
        .map_err(|e| ChangelogError::ReadFailed {
            path: changelog_path.to_path_buf(),
            message: e.to_string(),
        })?
        .unwrap_or_else(|| format!("# {display_name}\n\n"));

    // Normalise CRLF → LF so the prefix patterns always match, then restore
    // the original line endings on the way out if the file used CRLF.
    let had_crlf = existing.contains("\r\n");
    let normalised = if had_crlf {
        existing.replace("\r\n", "\n")
    } else {
        existing.clone()
    };

    // Bug 8 guard: if the version heading we are about to insert already exists
    // in the file, skip the write entirely (idempotent behaviour). The heading
    // is the first line of `rendered` (e.g. "## 1.0.0").
    let version_heading = rendered.lines().next().unwrap_or("").trim();
    if !version_heading.is_empty() && normalised.lines().any(|l| l.trim() == version_heading) {
        return Ok(());
    }

    // All three header shapes (blank line after the H1, no blank line, or no
    // matching H1 at all -- e.g. a casing change, HTML anchor, or package
    // rename) splice the new entry in identically; only what counts as
    // "the rest of the file to keep" differs, so compute just that here.
    let rest: &str = if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n\n")) {
        rest
    } else if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n")) {
        rest
    } else {
        // No matching H1 found: emit the correct H1 first so the output is
        // well-formed, keeping the entire existing content as the body.
        &normalised
    };

    let mut new_content = String::new();
    new_content.push_str(&format!("# {display_name}\n\n"));
    new_content.push_str(rendered);
    if !rendered.ends_with('\n') {
        new_content.push('\n');
    }
    new_content.push('\n');
    new_content.push_str(rest);

    if had_crlf {
        new_content = new_content.replace('\n', "\r\n");
    }

    callisto_model::atomic::atomic_write(&full_path, &new_content, permit).map_err(|e| ChangelogError::WriteFailed {
        path: changelog_path.to_path_buf(),
        message: e.to_string(),
    })
}

